127	let fieldPackDropPoseAuthority: FieldPackDropPoseAuthority | null = null;
128	
129	function sameFieldPackScope(
130	  authority: FieldPackDropPoseAuthority,
131	  worldId: string,
132	  storyRunId: number
133	): boolean {
134	  return authority.worldId === worldId && authority.storyRunId === storyRunId;
135	}
