151	  if (existing && !sameFieldPackScope(existing, input.worldId, input.storyRunId)) {
152	    resetFieldPackDropPoseAuthority();
153	  } else if (existing && fieldPackPoseLocked(existing)) {
154	    return existing;
155	  } else if (
156	    existing
157	    && existing.terrainRevision === input.terrainRevision
158	    && existing.source === input.source
159	  ) {
160	    return existing;
161	  }
162	
163	  const safe = getFieldPackPose(input.planetSize, input.terrainSeed, input.terrain);
