279	/**
280	 * The field pack torn from W-7744 during A4. This is a validated prop spawn, not
281	 * a decorative offset: it needs a level dry footprint and clear humanoid
282	 * approach because the kit is the sole causal source of the Maw repair.
283	 */
284	function getFieldPackPose(
285	  planetSize: number,
286	  terrainSeed: number,
287	  terrain: AgentSurfaceTerrainQuery = proceduralAgentTerrain(planetSize, terrainSeed)
288	): FieldPackSafePose | null {
289	  const tree = getHeroTreePose(planetSize, terrainSeed);
290	  const preferred = tree.position.clone().add(new THREE.Vector3(7, 0, -5));
291	  const site = findValidSpawnSite(
292	    spawnTerrainFromAgent(terrain),
293	    planetSize,
294	    preferred,
295	    { kind: 'player', face: 'top', maxSearchRadius: 10 }
296	  );
297	  if (!site) return null;
298	  return {
299	    position: voxelCoordToWorld(
300	      site.supportVoxel.x,
301	      site.supportVoxel.y,
302	      site.supportVoxel.z
303	    ).addScaledVector(site.up, VOXEL_SCALE / 2 + 0.18),
304	    up: site.up.clone(),
305	    supportVoxel: Object.freeze({ ...site.supportVoxel }),
306	    relocated: site.relocated
307	  };
308	}
309	
310	const pondCache = new Map<string, PondPose | null>();
311	
312	/**
313	 * Deterministic nearest-water scan on the top face: ring-search outward from the
314	 * arrival column for a flooded cell above ground (prefer depth ≥ 2 — the dive
315	 * needs a floor below the surface). Cached per size:seed; asserted in
316	 * storyWorld.test.ts (the pinned world must keep its pond within reach).
317	 */
318	function getPondPose(
319	  planetSize: number,
320	  terrainSeed: number,
321	  worldId?: string
322	): PondPose | null {
323	  const resolvedWorldId = worldId ?? STORY_PRIMARY_WORLD_ID;
324	  const key = `${planetSize}:${terrainSeed}:${resolvedWorldId}`;
325	  const cached = pondCache.get(key);
326	  if (cached !== undefined) return cached;
327	
328	  const gen = getWorldGen(planetSize, terrainSeed, resolvedWorldId).generator;
329	  const arrival = findTopFaceSurfaceVoxel(
330	    planetSize,
331	    terrainSeed,
332	    { x: 4, z: -4 },
333	    resolvedWorldId
334	  );
335	
336	  const dryShoreNear = (waterX: number, waterZ: number): THREE.Vector3 | null => {
337	    const candidates: Array<{ x: number; z: number; radius: number; arrivalDistance: number }> = [];
338	    for (let radius = 1; radius <= 6; radius++) {
339	      for (let dx = -radius; dx <= radius; dx++) {
340	        for (let dz = -radius; dz <= radius; dz++) {
341	          if (Math.max(Math.abs(dx), Math.abs(dz)) !== radius) continue;
342	          const x = waterX + dx;
343	          const z = waterZ + dz;
344	          candidates.push({
345	            x,
346	            z,
347	            radius,
348	            arrivalDistance: (x - arrival.x) ** 2 + (z - arrival.z) ** 2
349	          });
350	        }
351	      }
352	    }
353	    // Nearest shoreline first; ties prefer the arrival side so the authored walk
354	    // approaches the pond instead of circling behind it.
355	    candidates.sort((a, b) => a.radius - b.radius
356	      || a.arrivalDistance - b.arrivalDistance
357	      || a.x - b.x
358	      || a.z - b.z);
359	    for (const candidate of candidates) {
360	      const ground = findTopFaceSurfaceVoxel(
361	        planetSize,
362	        terrainSeed,
363	        candidate,
364	        resolvedWorldId
365	      );
