const corridorMin = { x: Math.min(startRef.x, endRef.x) - 20, z: Math.min(startRef.z, endRef.z) - 20 };
const corridorMax = { x: Math.max(startRef.x, endRef.x) + 20, z: Math.max(startRef.z, endRef.z) + 20 };
